// Where each data item (ids from the published notice) is collected, so the
// privacy policy can itemise data by collection point (DPDP Rules 2025
// Rule 3(b)(i)). Items in the notice that are not listed here are still
// shown, under "other", so the policy can never hide a data item.
export const COLLECTION_POINTS=[{key:"account",items:["name","email","phone","account_password","google_profile"]},{key:"phone",items:["phone"]},{key:"orders",items:["delivery_address","order_history","payment_reference","invoice_records"]},{key:"location",items:["precise_location"]},{key:"chat",items:["order_chat"]},{key:"notifications",items:["push_token"]},{key:"optional",items:["usage_events","session_interactions","error_diagnostics","marketing_contact","preferences_history"]}];export function groupDataItems(){let dataItems=arguments.length>0&&arguments[0]!==undefined?arguments[0]:[];const byId=Object.fromEntries(dataItems.map(d=>[d.id,d]));const listed=new Set(COLLECTION_POINTS.flatMap(g=>g.items));const groups=COLLECTION_POINTS.map(g=>({key:g.key,items:g.items.map(id=>byId[id]).filter(Boolean)})).filter(g=>g.items.length);const other=dataItems.filter(d=>!listed.has(d.id));if(other.length)groups.push({key:"other",items:other});return groups;}
